const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to await EE evaluate
  const getInfo = (eeObj) =>
    new Promise((resolve, reject) => eeObj.evaluate(resolve, reject));

  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Rectangle([113.8, 22.1, 114.5, 22.6], null, false);
    const scale = 3000;
    const p1 = { start: '2020-01-01', end: '2020-01-21', label: 'Jan 1–20, 2020' };
    const p2 = { start: '2020-02-10', end: '2020-02-26', label: 'Feb 10–25, 2020' };

    // 2. Data Acquisition & Fallback
    async function getS5PCollection(start, end) {
      const sources = [
        { id: 'COPERNICUS/S5P/OFFL/L3_NO2', name: 'OFFL' },
        { id: 'COPERNICUS/S5P/NRTI/L3_NO2', name: 'NRTI' },
      ];
      for (const src of sources) {
        const col = ee
          .ImageCollection(src.id)
          .filterDate(start, end)
          .filterBounds(region);
        const sz = await getInfo(col.size());
        if (sz && sz > 0) {
          return { col, name: src.name, size: sz };
        }
      }
      return { col: null, name: null, size: 0 };
    }

    function maskS5P(img) {
      // Mask low-quality pixels
      return img.updateMask(img.select('qa_value').gte(0.75));
    }

    async function computeStats(info) {
      const colMasked = info.col.map(maskS5P).select('tropospheric_NO2_column_number_density');
      const meanImg = colMasked.mean();

      const validCount = ee.Number(
        meanImg.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9,
        }).get('tropospheric_NO2_column_number_density')
      );

      const totalCount = ee.Number(
        ee.Image.constant(1).rename('ones').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9,
        }).get('ones')
      );

      const meanVal = ee.Number(
        meanImg.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9,
        }).get('tropospheric_NO2_column_number_density')
      );

      const stats = {
        images: info.size,
        source: info.name,
        validCount: await getInfo(validCount),
        totalCount: await getInfo(totalCount),
        mean: await getInfo(meanVal),
      };
      return stats;
    }

    const p1Info = await getS5PCollection(p1.start, p1.end);
    const p2Info = await getS5PCollection(p2.start, p2.end);

    if (!p1Info.col || !p2Info.col) {
      console.log(`Region: Hong Kong; Scale: ${scale} m`);
      console.log(`${p1.label} Images: ${p1Info.size || 0} (Source: ${p1Info.name || 'None'})`);
      console.log(`${p2.label} Images: ${p2Info.size || 0} (Source: ${p2Info.name || 'None'})`);
      console.log('C1: Empty Collection');
      return;
    }

    const p1Stats = await computeStats(p1Info);
    const p2Stats = await computeStats(p2Info);

    // 3. Processing checks
    if ((p1Stats.validCount || 0) === 0 || (p2Stats.validCount || 0) === 0) {
      console.log(`Region: Hong Kong; Scale: ${scale} m`);
      console.log(`${p1.label} Images: ${p1Stats.images} (Source: ${p1Stats.source})`);
      console.log(`${p2.label} Images: ${p2Stats.images} (Source: ${p2Stats.source})`);
      console.log('No valid pixels after masking in one or both periods.');
      console.log('C2: No Valid Pixels');
      return;
    }

    // 4. Calculation & Validation
    const invalid =
      p1Stats.mean == null ||
      p2Stats.mean == null ||
      !isFinite(p1Stats.mean) ||
      !isFinite(p2Stats.mean) ||
      p1Stats.mean <= 0 ||
      p2Stats.mean <= 0 ||
      p1Stats.mean > 1e-2 ||
      p2Stats.mean > 1e-2;

    if (invalid) {
      console.log('Calculation produced invalid results.');
      console.log('C3: Calculation Failure');
      return;
    }

    // 5. Evidence output
    const p1Pct = (100 * p1Stats.validCount / p1Stats.totalCount).toFixed(1);
    const p2Pct = (100 * p2Stats.validCount / p2Stats.totalCount).toFixed(1);
    const delta = p2Stats.mean - p1Stats.mean;
    const ratio = p2Stats.mean / p1Stats.mean;

    function fmtExp(x) { return Number(x).toExponential(2); }

    console.log(`Region: Hong Kong; Scale: ${scale} m`);
    console.log(`${p1.label} Images: ${p1Stats.images} (Source: ${p1Stats.source})`);
    console.log(`${p1.label} Valid Pixels: ${p1Stats.validCount}/${p1Stats.totalCount} (${p1Pct}%)`);
    console.log(`${p1.label} Mean NO2: ${fmtExp(p1Stats.mean)} mol/m^2`);
    console.log(`${p2.label} Images: ${p2Stats.images} (Source: ${p2Stats.source})`);
    console.log(`${p2.label} Valid Pixels: ${p2Stats.validCount}/${p2Stats.totalCount} (${p2Pct}%)`);
    console.log(`${p2.label} Mean NO2: ${fmtExp(p2Stats.mean)} mol/m^2`);
    console.log(`Delta (P2 - P1): ${fmtExp(delta)} mol/m^2; Ratio P2/P1: ${ratio.toFixed(2)}`);

    // 6. Final Answer
    const decreased = p2Stats.mean < p1Stats.mean;
    console.log(decreased ? 'A: Yes' : 'B: No');
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
